var a=`0841-idli`;var t=`world-0841`;var n=`IN`;var r=`south-asia`;var s=8;var d=1234;var o={en:`Idli`,ua:`Ідлі`};var l={en:`Idli is a India dish made with idli rice, urad dal, sambar powder. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Ідлі, страва кухні країни Індія. Основні складники: рис для ідлі, урід дал, приправа самбар. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var m=[{en:`Soak the listed rice, grains or noodles in clean water for about 480 minutes as appropriate, then drain; grind rice and urad for batter if required by this dish.`,ua:`Замочіть зазначені рис, крупи або локшину у чистій воді приблизно на 480 хвилин залежно від продукту, потім злийте; для тіста за потреби подрібніть рис і урад.`,t:[`rice-soaking`],m:480,i:[[`idli-rice`,370,`g`],[`urad-dal`,125,`g`],[`water`,1100,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:15,i:[[`water`,260,`ml`],[`table-salt`,7,`g`]]},{en:`Leave the mixed rice-and-legume batter loosely covered in a clean warm place for about 720 minutes until aerated and tangy. Fermentation times vary; avoid overheating.`,ua:`Залиште суміш рисового тіста з бобовими нещільно накритою в чистому теплому місці на приблизно 720 хвилин до бульбашок та легкої кислинки. Час змінюється; не перегрівайте.`,t:[`mixed-grain-fermentation`],m:720,i:[]},{en:`Pour fermented batter into lightly oiled idli molds and steam covered until fluffy and fully set, about 14–16 minutes.`,ua:`Розлийте ферментоване тісто у злегка змащені формочки для ідлі та пропарте під кришкою до пухкої повністю готової середини, близько 14–16 хвилин.`,t:[`steaming`],m:16,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`sambar-powder`,4,`g`]]}];var u={slug:a,id:t,country:`IN`,region:r,servings:8,minutes:d,title:o,text:l,steps:m};export{n as country,u as default,t as id,d as minutes,r as region,s as servings,a as slug,m as steps,l as text,o as title};